style.css:
/* ============================================================
   ProtonMail — Glass & Ember Theme
   Glassmorphism + matte grain + monochrome + fire accents
   Install via: Stylus extension → mail.proton.me
   ============================================================ */

/* ── Noise grain overlay (pseudo-element on body) ── */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
  opacity: 0.04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 180px 180px;
}

/* ── Ambient fire glow on page background ── */
html, body {
  background-color: #0a0a0a !important;
  background-image:
    radial-gradient(ellipse 55% 45% at 15% 65%, rgba(200,40,20,0.18) 0%, transparent 70%),
    radial-gradient(ellipse 45% 35% at 80% 25%, rgba(240,100,20,0.12) 0%, transparent 65%),
    radial-gradient(ellipse 35% 25% at 50% 95%, rgba(245,180,30,0.08) 0%, transparent 55%) !important;
  color: rgba(255,255,255,0.85) !important;
}

/* ── Glass mixin (applied to panels) ── */
nav,
[class*="sidebar"],
[class*="Sidebar"],
[class*="NavigationContainer"],
[class*="navigation"] {
  background: rgba(255,255,255,0.04) !important;
  backdrop-filter: blur(24px) saturate(1.5) !important;
  -webkit-backdrop-filter: blur(24px) saturate(1.5) !important;
  border-right: 0.5px solid rgba(255,255,255,0.08) !important;
}

/* ── Toolbar / top bar ── */
[class*="toolbar"],
[class*="Toolbar"],
[class*="topbar"],
[class*="Topbar"],
header,
[class*="header"]:not([class*="email"]):not([class*="message"]) {
  background: rgba(255,255,255,0.03) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border-bottom: 0.5px solid rgba(255,255,255,0.07) !important;
  color: rgba(255,255,255,0.85) !important;
}

/* ── Compose button ── */
[class*="compose"],
[class*="Compose"],
button[class*="primary"] {
  background: rgba(210,50,30,0.78) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border: 0.5px solid rgba(255,110,70,0.3) !important;
  border-radius: 9px !important;
  color: #fff !important;
}

[class*="compose"]:hover,
button[class*="primary"]:hover {
  background: rgba(230,80,30,0.85) !important;
}

/* ── Nav items ── */
[class*="NavigationItem"],
[class*="navItem"],
[class*="nav-item"] {
  color: rgba(255,255,255,0.4) !important;
  border-radius: 8px !important;
}

[class*="NavigationItem"]:hover,
[class*="navItem"]:hover {
  background: rgba(255,255,255,0.05) !important;
  color: rgba(255,255,255,0.7) !important;
}

[class*="NavigationItem"][aria-current="page"],
[class*="active"] {
  background: rgba(210,50,30,0.18) !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  border: 0.5px solid rgba(210,50,30,0.28) !important;
  color: rgba(255,120,90,0.95) !important;
}

/* ── Email list pane ── */
[class*="item-container"],
[class*="ItemContainer"],
[class*="MessageItem"],
[class*="ConversationItem"],
[class*="listItem"],
[class*="ListItem"] {
  background: transparent !important;
  border-bottom: 0.5px solid rgba(255,255,255,0.05) !important;
  color: rgba(255,255,255,0.65) !important;
}

[class*="item-container"]:hover,
[class*="MessageItem"]:hover,
[class*="ConversationItem"]:hover {
  background: rgba(255,255,255,0.03) !important;
}

[class*="item-container"][aria-current],
[class*="selected"],
[class*="Selected"],
[class*="active"][class*="item"] {
  background: rgba(210,50,30,0.12) !important;
  border-left: 2px solid rgba(210,50,30,0.55) !important;
}

/* ── Unread items ── */
[class*="unread"] [class*="sender"],
[class*="unread"] [class*="subject"],
[class*="Unread"] {
  color: rgba(255,255,255,0.88) !important;
}

/* ── Message reading pane ── */
[class*="message-content"],
[class*="MessageContent"],
[class*="emailContent"],
[class*="conversationView"],
[class*="readingPane"],
[class*="ReadingPane"] {
  background: rgba(255,255,255,0.02) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  color: rgba(255,255,255,0.82) !important;
  border-left: 0.5px solid rgba(255,255,255,0.06) !important;
}

/* ── Inputs ── */
input, textarea, select {
  background: rgba(255,255,255,0.06) !important;
  border: 0.5px solid rgba(255,255,255,0.1) !important;
  border-radius: 8px !important;
  color: rgba(255,255,255,0.85) !important;
}

input::placeholder, textarea::placeholder {
  color: rgba(255,255,255,0.3) !important;
}

input:focus, textarea:focus {
  border-color: rgba(210,50,30,0.6) !important;
  outline: none !important;
  box-shadow: 0 0 0 3px rgba(210,50,30,0.15) !important;
  background: rgba(255,255,255,0.08) !important;
}

/* ── Dropdowns & modals — glass panels ── */
[class*="dropdown"],
[class*="Dropdown"],
[class*="modal"],
[class*="Modal"],
[class*="popover"],
[class*="Popover"],
[class*="dialog"],
[class*="Dialog"] {
  background: rgba(18,18,18,0.75) !important;
  backdrop-filter: blur(32px) saturate(1.6) !important;
  -webkit-backdrop-filter: blur(32px) saturate(1.6) !important;
  border: 0.5px solid rgba(255,255,255,0.1) !important;
  border-radius: 12px !important;
  color: rgba(255,255,255,0.85) !important;
  box-shadow: 0 8px 40px rgba(0,0,0,0.5) !important;
}

/* ── Links ── */
a, [class*="link"] {
  color: rgba(240,110,60,0.9) !important;
}
a:hover { color: rgba(245,190,50,0.9) !important; }

/* ── Labels / tags ── */
[class*="label"]:not(label),
[class*="Label"]:not(label),
[class*="tag"],
[class*="Tag"] {
  background: rgba(200,40,20,0.18) !important;
  backdrop-filter: blur(6px) !important;
  color: rgba(255,110,80,0.9) !important;
  border: 0.5px solid rgba(200,40,20,0.28) !important;
  border-radius: 99px !important;
}

/* ── Badges / counters ── */
[class*="badge"],
[class*="Badge"],
[class*="counter"],
[class*="unreadCount"] {
  background: rgba(210,50,30,0.8) !important;
  color: #fff !important;
  border-radius: 99px !important;
}

/* ── Unread indicator dot ── */
[class*="unreadDot"],
[class*="unread-dot"] {
  background: #e03820 !important;
  box-shadow: 0 0 6px rgba(220,60,30,0.5) !important;
}

/* ── Dividers ── */
hr, [class*="separator"], [class*="Separator"] {
  border-color: rgba(255,255,255,0.06) !important;
}

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 5px; background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: rgba(210,50,30,0.5); }

/* ── Text selection ── */
::selection {
  background: rgba(210,50,30,0.35) !important;
  color: #fff !important;
}

/* ── Storage bar ── */
[class*="storage"] [class*="bar"],
[class*="StorageBar"],
[class*="progressBar"] {
  background: rgba(255,255,255,0.08) !important;
  border-radius: 99px !important;
}

[class*="storage"] [class*="fill"],
[class*="StorageFill"],
[class*="progress"]:not([class*="container"]) {
  background: linear-gradient(to right, #e03820, #f07020) !important;
}

/* ── Avatar circles ── */
[class*="avatar"],
[class*="Avatar"],
[class*="initials"],
[class*="Initials"] {
  border: 0.5px solid rgba(255,255,255,0.08) !important;
  color: rgba(255,160,100,0.9) !important;
  background: rgba(200,40,20,0.22) !important;
}
